import pyomo.environ as pyo

DATA = {
    "catalysts": ["palladium_heavy", "platinum_heavy"],
    "resources": ["platinum", "palladium"],
    # conversion rate (units CO2 per second) per catalyst unit
    "conversion_rate": {
        "palladium_heavy": 5,
        "platinum_heavy": 4,
    },
    # resource usage: usage[resource][catalyst]
    "usage": {
        "platinum":  {"palladium_heavy": 15, "platinum_heavy": 20},
        "palladium": {"palladium_heavy": 25, "platinum_heavy": 14},
    },
    # available resource amounts
    "availability": {
        "platinum": 450,
        "palladium": 390,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.C = pyo.Set(initialize=d["catalysts"])
    model.R = pyo.Set(initialize=d["resources"])

    # Variables: number of units of each catalyst (discrete units)
    model.catalyst = pyo.Var(model.C, within=pyo.NonNegativeIntegers)

    # Objective: maximize total CO2 conversion rate
    def obj_rule(m):
        return sum(d["conversion_rate"][c] * m.catalyst[c] for c in m.C)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraints: one per resource availability
    def resource_rule(m, r):
        return sum(d["usage"][r][c] * m.catalyst[c] for c in m.C) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model


